def binary_search(values, target):
    left, right = 0, len(values) - 1
    while left <= right:
        middle = (left + right) // 2
        if values[middle] == target:
            return middle
        if values[middle] < target:
            left = middle + 1
        else:
            right = middle - 1
    return -1

print(binary_search([2, 4, 7, 11], 7))

def two_sum(numbers, target):
    seen = {}
    for i, number in enumerate(numbers):
        if target - number in seen:
            return (seen[target - number], i)
        seen[number] = i
    return None

print(two_sum([2, 7, 11, 15], 9))

def valid(text):
    opening = {"(", "[", "{"}
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for char in text:
        if char in opening:
            stack.append(char)
        elif char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return False
    return not stack

print(valid("([])"))
print(valid("([)]"))

def max_window_sum(values, k):
    if not 1 <= k <= len(values):
        raise ValueError("invalid window")
    current = sum(values[:k])
    best = current
    for right in range(k, len(values)):
        current += values[right] - values[right - k]
        best = max(best, current)
    return best

print(max_window_sum([1, 4, 2, 7, 3], 3))

