def merge(a, b):
    i = j = 0
    output = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            output.append(a[i]); i += 1
        else:
            output.append(b[j]); j += 1
    return output + a[i:] + b[j:]

